"OLAYLAR_ARKEOLOJI_ZINCIR:-0322-06-10:0":{"b": ["Aleksandria: Fillon periudha e Mbretërisë Ptolemaike (Lagide)", "e3274526"], "d": ["Aleksandria: Fillon periudha e Mbretërisë Ptolemaike (Lagide). Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "a57c0b24"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0329-01-01:0":{"b": ["Ekbatana, Hamadani: Perandoria Akemenide (Perse) → Perandoria e Aleksandrit të Madh (ANTIK-ISKENDER-1113-B)", "7b1734be"], "d": ["Në pikat Ekbatana, Hamadan zotërimi kalon nga Perandoria Akemenide (Perse) te intervali pa zotërues. Të dhënat e burimit për kalimin: viti 6 i Nabonidit (550/549): Kiri II mund Astiagun, merr Ekbatanën dhe e çon thesarin e saj në Anshan | Burimi: Brown, S. C., \"Ecbatana\", Encyclopaedia Iranica VIII/1, 1997 (rev. 2011) | https://web.archive.org/web/2025/https://www.iranicaonline.org/articles/ecbatana | «records that Cyrus II defeated Astyages, captured Ecbatana, and removed its treasury to Anshan»", "68589a0a"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0330-10-22:0":{"b": ["Babilonia, Uruku: Perandoria Akemenide (Perse) → Perandoria e Aleksandrit të Madh", "6624ab48"], "d": ["Në pikat Babiloni, Uruk zotërimi kalon nga Perandoria Akemenide (Perse) te Perandoria e Aleksandrit të Madh. Të dhënat e burimit për kalimin: Aleksandri merr Babiloninë (331); burimi është përmbledhja e Livius-it, Arriani 3.16 nuk u lexua | Burimi: Lendering, J., Livius.org: Babylon | https://www.livius.org/articles/place/babylon/ | «In 331, the Macedonian conqueror Alexander the Great, who was fighting a war against the Persians, captured Babylon»", "69104647"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0337-01-01:0":{"b": ["Kapua: Fillon periudha e Republikës Romake", "36452a38"], "d": ["Kapua: Fillon periudha e Republikës Romake. Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "5cb1bd12"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0349-01-01:0":{"b": ["Xi'an (Chang'an): Fillon periudha e Shtetit Qin", "dc6688ef"], "d": ["Xi'an (Chang'an): Fillon periudha e Shtetit Qin. Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "e051c6fb"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0395-01-01:0":{"b": ["Veji: Qytet-shtetet etruske (Lidhja e Dymbëdhjetë Qyteteve) → Republika Romake", "94377ac0"], "d": ["Në pikat Veji zotërimi kalon nga Qytet-shtetet etruske (Lidhja e Dymbëdhjetë Qyteteve) te Republika Romake. Të dhënat e burimit për kalimin: Livi 5.22 (Roberts, Perseus 1999.02.0026): pasi nga Veji u bart gjithë pasuria njerëzore, statuja e Junonës u dërgua në Romë; qyteti u mor. Viti p.e.s. nuk gjendet te Livi (viti i konsullit/diktatorit Kamil përputhet me Fasti-t).", "afe95710"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0401-01-01:0":{"b": ["Memfisi (Men-nefer / Mit Rahina): Merr fund intervali pa zotërues", "3cb446ba"], "d": ["Memfisi (Men-nefer / Mit Rahina): Merr fund intervali pa zotërues. Kjo datë nuk është ngjarje më vete, ajo tregon fundin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "fe82b0fd"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0403-01-01:0":{"b": ["Memfisi (Men-nefer / Mit Rahina): Egjipti Akemenid (Dinastia 27, sundimi i 1-rë pers) → interval pa zotërues", "d24cbed5"], "d": ["Në pikat Memfis (Men-nefer / Mit Rahina) zotërimi kalon nga Egjipti Akemenid (Dinastia 27, sundimi i 1-rë pers) te intervali pa zotërues. Të dhënat e burimit për kalimin: beteja e Peluzit 525; në fund të muajit Kambizi u shpall mbret i Egjiptit; sundimi i 1-rë pers mori fund ~402; \"Egypt was governed from Memphis by a satrap\" [Bresciani, Iranica Egypt i; Dandamayev, Iranica Cambyses]", "07561e90"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0517-01-01:0":{"b": ["Persepoli: Fillon periudha e Perandorisë Akemenide (Perse)", "ca9cece4"], "d": ["Persepoli: Fillon periudha e Perandorisë Akemenide (Perse). Kjo datë nuk është ngjarje më vete, ajo tregon fillimin e kësaj periudhe; hollësitë dhe burimet janë më poshtë.", "6231ff7e"]},
