"OLAYLAR_DUNYA_AVRUPA_MO:-0684-01-01:0":{"b": ["Nisi Lufta II e Mesenisë", "760d8edb"], "d": ["Sparta shtypi kryengritjen e Mesenisë dhe forcoi sistemin e helotëve.", "7f1466e7"]},
