"OLAYLAR_DUNYA_AVRUPA_MO:-0699-01-01:0":{"b": ["Lufta Lelantine: luftë e gjatë midis Kalkidës dhe Eretrisë", "ec4372c3"], "d": ["Luftë midis dy qyteteve të mëdha të Eubesë për fushën e Lelantit; shumë shtete greke morën anë.", "140a24c1"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0731-01-01:0":{"b": ["U themelua Regioni", "9b7b9f57"], "d": ["Koloni në skajin e Italisë së Jugut.", "6de952a4"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0732-01-01:0":{"b": ["Korkira (Kerkira) u themelua nga korintasit", "6fb853e7"], "d": ["Koloni korintase në hyrje të Adriatikut.", "b7b072be"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0733-01-01:0":{"b": ["U themelua Naksosi (Sicili): kolonia e parë greke e Sicilisë", "4850886a"], "d": ["Kalkidasit, nën udhëheqjen e Thukleut, themeluan në Sicilinë lindore kolonin e parë greke.", "407aaab5"]},
